#!/usr/bin/env python3
"""Round 93b tiles (27 September): scripts/aqueduct.py builds Aqueduct's projected water stress (WRI's file) and farmland water stress (Global Forest Watch's data-lake copy) as vector tiles for the map. Upload to the culprits-tiles-more repo's patches folder. Safe to run twice."""
import base64, os, pathlib, sys
if not os.path.isdir("scripts"):
    sys.exit("Run this from the culprits-tiles-more folder.")
p = pathlib.Path("scripts/aqueduct.py")
data = base64.b64decode("""""")
if p.exists() and p.read_bytes() == data:
    print("Already applied. Nothing changed.")
else:
    p.write_bytes(data); print("written:", p)
